--
-- Table structure for table `scrape_logs`
--

DROP TABLE IF EXISTS `scrape_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scrape_logs` (
  `scrape_log_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `locality_id` int unsigned NOT NULL,
  `category_id` int unsigned NOT NULL,
  `next_scrape` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`scrape_log_id`),
  UNIQUE KEY `scrape_logs_locality_id_IDX` (`locality_id`,`category_id`) USING BTREE,
  KEY `scrape_logs_categories_FK` (`category_id`),
  CONSTRAINT `scrape_logs_categories_FK` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `scrape_logs_localities_FK` FOREIGN KEY (`locality_id`) REFERENCES `localities` (`locality_id`)
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

