CREATE TABLE `services` (
  `service_id` int unsigned NOT NULL AUTO_INCREMENT,
  `place_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `service_name` varchar(255) NOT NULL,
  `latitude` decimal(11,8) NOT NULL,
  `longitude` decimal(11,8) NOT NULL,
  `rating` int DEFAULT NULL,
  `reviews` int DEFAULT NULL,
  `unclaimed_listing` tinyint(1) DEFAULT NULL,
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `phone` varchar(100) DEFAULT NULL,
  `website` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `reviews_link` varchar(255) DEFAULT NULL,
  `photos_link` varchar(255) DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  `types` varchar(500) DEFAULT NULL,
  `type_id` varchar(255) DEFAULT NULL,
  `type_ids` varchar(500) DEFAULT NULL,
  `operating_hours` varchar(500) DEFAULT NULL,
  `user_review` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `thumbnail` varchar(500) DEFAULT NULL,
  `valid_service` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`service_id`),
  UNIQUE KEY `services_unique` (`place_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1495 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
